        IFF(SUP_SEGMENT_1 IS NULL, '-2', CONCAT_WS('||', SUP_SEGMENT_1, BKCC)) as DRVD_SUPPLIER_BKCC
        , /*To handle the optional null default for the Hash key generation and to match with the Ghost Key Hash value */
        IFF((SUP_SEGMENT_1 IS NULL OR VENDOR_SITE_ID IS NULL), '-2', CONCAT_WS('||',SUP_SEGMENT_1,VENDOR_SITE_ID,BKCC)) as DRVD_SUPPLIER_SITE_BKCC
